// Emitter key components and the address they must derive to. These are the
// shared cross-language vector generated by
// node/pkg/cantonclient/vectorgen_test.go (TestCantonDamlFixtures) and
// asserted on the Daml side by Test.TestCore:testAddressVector — DO NOT edit one
// side without regenerating and updating both.
const (
	sampleRegistrar   = "vector-operator::1220deadbeef"
	sampleOwner       = "vector-owner::1220cafebabe"
	sampleEmitterID   = uint64(7)
	sampleWantAddrHex = "45ae8886d1c165b071d3b1202fe81ebedc39f61a6a91a1d13140eb64857f3f2b"
)

// Update ids reported by LocalNet participants.
const (
	sampleUpdateIDHex = "1220ac5126912ade361264f7d40c4711a72dc9b3d12e9ec044a07d5df586b2fe397b"
	reobsUpdateIDHex  = "122053276773593cd4d44463b8a459f24fa089e5abd4a4b0b0103153e5898d59f072"
)

func mustParseUpdateID(updateIDHex string) cantonclient.UpdateID {
	updateID, err := cantonclient.ParseUpdateID(updateIDHex)
	if err != nil {
		panic(err)
	}
	return updateID
}

// wantAddr is the emitter address the watcher must derive from the sample key.
func wantAddr(t *testing.T) vaa.Address {
	t.Helper()
	b, err := hex.DecodeString(sampleWantAddrHex)
	require.NoError(t, err)
	var a vaa.Address
	copy(a[:], b)
	return a
}

// fakeClient is a programmable CantonClient that lets a test drive the
// subscription (push events, fail it) so the Run loop is testable without a
// live participant.
type fakeClient struct {
	mu sync.Mutex

	ledgerEnd      int64
	ledgerEndErr   error
	ledgerEndCalls int

	byUpdateID             map[cantonclient.UpdateID]cantonclient.CantonTransaction
	getTransactionErr      error
	getTransactionRequests []cantonclient.UpdateID

	subCalls   int
	subBegin   int64                   // beginExclusive of the latest SubscribeUpdates
	subTmpl    cantonclient.TemplateID // template filter of the latest SubscribeUpdates
	subChoice  string                  // choice name of the latest SubscribeUpdates
	out        chan<- cantonclient.CantonMessageEvent
	sub        *cantonclient.Subscription
	subscribed chan struct{} // signaled on each SubscribeUpdates
}

func newFakeClient() *fakeClient {
	return &fakeClient{
		byUpdateID: map[cantonclient.UpdateID]cantonclient.CantonTransaction{},
		subscribed: make(chan struct{}, 16),
	}
}

func (f *fakeClient) GetLedgerEnd(_ context.Context) (int64, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.ledgerEndCalls++
	if f.ledgerEndErr != nil {
		return 0, f.ledgerEndErr
	}
	return f.ledgerEnd, nil
}

func (f *fakeClient) SubscribeUpdates(_ context.Context, begin int64, tmpl cantonclient.TemplateID, choice string, out chan<- cantonclient.CantonMessageEvent) (*cantonclient.Subscription, error) {
	f.mu.Lock()
	f.subCalls++
	f.subBegin = begin
	f.subTmpl = tmpl
	f.subChoice = choice
	f.out = out
	sub := cantonclient.NewSubscription(func() {})
	f.sub = sub
	subscribed := f.subscribed
	f.mu.Unlock()
	if subscribed != nil {
		select {
		case subscribed <- struct{}{}:
		default:
		}
	}
	return sub, nil
}

func (f *fakeClient) GetTransactionByUpdateID(_ context.Context, updateID cantonclient.UpdateID, _ cantonclient.TemplateID, _ string) (cantonclient.CantonTransaction, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.getTransactionRequests = append(f.getTransactionRequests, updateID)
	if f.getTransactionErr != nil {
		return cantonclient.CantonTransaction{}, f.getTransactionErr
	}
	transaction, found := f.byUpdateID[updateID]
	if !found {
		return cantonclient.CantonTransaction{}, fmt.Errorf("GetUpdateById(%s): UPDATE_NOT_FOUND", updateID)
	}
	return transaction, nil
}

func (f *fakeClient) getTransactionRequestCount() int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return len(f.getTransactionRequests)
}

func (f *fakeClient) Close() error { return nil }

// waitSubscribed blocks until the data pump has (re)subscribed, so the stream
// channel is captured before the test pushes events.
func (f *fakeClient) waitSubscribed(t *testing.T) {
	t.Helper()
	select {
	case <-f.subscribed:
	case <-time.After(5 * time.Second):
		t.Fatal("watcher never subscribed")
	}
}

func (f *fakeClient) pushEvent(ev cantonclient.CantonMessageEvent) {
	f.mu.Lock()
	out := f.out
	f.mu.Unlock()
	out <- ev
}

func (f *fakeClient) failSubscription(err error) {
	f.mu.Lock()
	sub := f.sub
	f.mu.Unlock()
	sub.Fail(err)
}

func (f *fakeClient) subscribeCount() int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.subCalls
}

// subscribeArgs returns the (beginExclusive, template, choice) of the latest
// SubscribeUpdates call, so a test can assert the watcher streams from the
// right offset with the right filter.
func (f *fakeClient) subscribeArgs() (int64, cantonclient.TemplateID, string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.subBegin, f.subTmpl, f.subChoice
}

func testWatcher(msgC chan<- *common.MessagePublication) *Watcher {
	return NewWatcher("canton:5011", "pkg123", "Operator::ns", AuthConfig{}, true, msgC, make(chan *gossipv1.ObservationRequest))
}

func TestProcessMessageBuildsObservation(t *testing.T) {
	msgC := make(chan *common.MessagePublication, 1)
	w := testWatcher(msgC)

	ts := time.Unix(1_700_000_000, 0).UTC()
	w.processMessage(zap.NewNop(), cantonclient.CantonMessageEvent{
		ParticipantOffset: 42,
		UpdateID:          mustParseUpdateID(sampleUpdateIDHex),
		EffectiveAt:       ts,
		Message: cantonclient.CantonMessage{
			Registrar:        sampleRegistrar,
			Owner:            sampleOwner,
			EmitterID:        sampleEmitterID,
			Sequence:         7,
			Nonce:            99,
			ConsistencyLevel: 0,
			Payload:          []byte{0xde, 0xad},
		},
	}, false)

	got := <-msgC
	assert.Equal(t, vaa.ChainIDCanton, got.EmitterChain)
	assert.Equal(t, uint64(7), got.Sequence)
	assert.Equal(t, uint32(99), got.Nonce)
	assert.Equal(t, ts, got.Timestamp)
	assert.Equal(t, []byte{0xde, 0xad}, got.Payload)
	assert.False(t, got.IsReobservation)
	assert.Equal(t, mustParseUpdateID(sampleUpdateIDHex).TxID(), got.TxID)
	// Emitter address is keccak256(tag ‖ registrar ‖ owner ‖ emitterId).
	assert.Equal(t, wantAddr(t), got.EmitterAddress)
}

func TestProcessMessageDropsMissingKeyParty(t *testing.T) {
	for name, msg := range map[string]cantonclient.CantonMessage{
		"empty registrar": {Registrar: "", Owner: sampleOwner, EmitterID: 0},
		"empty owner":     {Registrar: sampleRegistrar, Owner: "", EmitterID: 0},
	} {
		t.Run(name, func(t *testing.T) {
			msgC := make(chan *common.MessagePublication, 1)
			w := testWatcher(msgC)

			w.processMessage(zap.NewNop(), cantonclient.CantonMessageEvent{
				ParticipantOffset: 1,
				UpdateID:          mustParseUpdateID(sampleUpdateIDHex),
				EffectiveAt:       time.Unix(1, 0),
				Message:           msg,
			}, false)

			select {
			case <-msgC:
				t.Fatal("expected no observation for a message missing an emitter key party")
			default:
			}
		})
	}
}

// TestDeriveEmitterAddressMatchesVector pins the Go encoder against the shared
// cross-language vector and checks that each key component affects the address,
// including that the length prefixes disambiguate the two variable-length parts.
func TestDeriveEmitterAddressMatchesVector(t *testing.T) {
	assert.Equal(t, wantAddr(t), deriveEmitterAddress(sampleRegistrar, sampleOwner, sampleEmitterID))

	base := deriveEmitterAddress(sampleRegistrar, sampleOwner, sampleEmitterID)
	assert.NotEqual(t, base, deriveEmitterAddress(sampleRegistrar, sampleOwner, sampleEmitterID+1), "id must matter")
	assert.NotEqual(t, base, deriveEmitterAddress(sampleOwner, sampleRegistrar, sampleEmitterID), "swapping parties must matter")

	// Without length prefixes, ("a","bc") and ("ab","c") would collide.
	assert.NotEqual(t,
		deriveEmitterAddress("a", "bc", 0),
		deriveEmitterAddress("ab", "c", 0),
		"length prefixes must disambiguate the party boundary")
}

// Participants assign different offsets to one update; guardians must agree on its TxID.
func TestProcessMessageTxIDIsIndependentOfParticipantOffset(t *testing.T) {
	msgC := make(chan *common.MessagePublication, 3)
	w := testWatcher(msgC)
	for _, participantOffset := range []int64{590, 762, 1381} {
		w.processMessage(zap.NewNop(), cantonclient.CantonMessageEvent{
			ParticipantOffset: participantOffset,
			UpdateID:          mustParseUpdateID(sampleUpdateIDHex),
			EffectiveAt:       time.Unix(1_700_000_000, 0).UTC(),
			Message:           cantonclient.CantonMessage{Registrar: sampleRegistrar, Owner: sampleOwner, EmitterID: sampleEmitterID},
		}, false)
	}
	wantTxID, err := hex.DecodeString(sampleUpdateIDHex)
	require.NoError(t, err)
	for range 3 {
		assert.Equal(t, wantTxID, (<-msgC).TxID)
	}
}

func TestProcessMessageDropsZeroUpdateID(t *testing.T) {
	msgC := make(chan *common.MessagePublication, 1)
	w := testWatcher(msgC)
	w.processMessage(zap.NewNop(), cantonclient.CantonMessageEvent{
		ParticipantOffset: 1,
		EffectiveAt:       time.Unix(1, 0),
		Message:           cantonclient.CantonMessage{Registrar: sampleRegistrar, Owner: sampleOwner},
	}, false)

	select {
	case <-msgC:
		t.Fatal("expected no observation for a zero update id")
	default:
	}
}

func TestHandleReobservation(t *testing.T) {
	msgC := make(chan *common.MessagePublication, 1)
	w := testWatcher(msgC)

	reobsUpdateID := mustParseUpdateID(reobsUpdateIDHex)
	client := newFakeClient()
	client.byUpdateID[reobsUpdateID] = cantonclient.CantonTransaction{
		ParticipantOffset: 1234,
		UpdateID:          reobsUpdateID,
		EffectiveAt:       time.Unix(1_700_000_001, 0).UTC(),
		Messages: []cantonclient.CantonMessage{{
			Registrar: sampleRegistrar,
			Owner:     sampleOwner,
			EmitterID: sampleEmitterID,
			Sequence:  3,
			Payload:   []byte{0x01},
		}},
	}

	w.handleReobservation(context.Background(), zap.NewNop(), client, &gossipv1.ObservationRequest{
		ChainId: uint32(vaa.ChainIDCanton),
		TxHash:  reobsUpdateID.TxID(),
	})

	got := <-msgC
	assert.True(t, got.IsReobservation)
	assert.Equal(t, uint64(3), got.Sequence)
	assert.Equal(t, reobsUpdateID.TxID(), got.TxID)
	assert.Equal(t, wantAddr(t), got.EmitterAddress)
	assert.Equal(t, []cantonclient.UpdateID{reobsUpdateID}, client.getTransactionRequests)
}

func TestHandleReobservationRejectsMalformedTxHash(t *testing.T) {
	legacyOffsetTxID := make([]byte, 32)
	legacyOffsetTxID[31] = 0x01
	cases := []struct {
		name   string
		txHash []byte
	}{
		{name: "empty", txHash: nil},
		{name: "legacy 32-byte offset", txHash: legacyOffsetTxID},
		{name: "update id one byte short", txHash: mustParseUpdateID(sampleUpdateIDHex).TxID()[:cantonclient.UpdateIDTxIDLen-1]},
		{name: "wrong multihash prefix", txHash: append([]byte{0x13, 0x20}, mustParseUpdateID(sampleUpdateIDHex).TxID()[2:]...)},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			msgC := make(chan *common.MessagePublication, 1)
			w := testWatcher(msgC)
			client := newFakeClient()
			w.handleReobservation(context.Background(), zap.NewNop(), client, &gossipv1.ObservationRequest{
				ChainId: uint32(vaa.ChainIDCanton),
				TxHash:  tc.txHash,
			})
			assert.Zero(t, client.getTransactionRequestCount(), "a malformed tx_hash must not reach the participant")
			assert.Empty(t, msgC)
		})
	}
}

func TestHandleReobservationRejectsMismatchedUpdateID(t *testing.T) {
	msgC := make(chan *common.MessagePublication, 1)
	w := testWatcher(msgC)
	requestedUpdateID := mustParseUpdateID(reobsUpdateIDHex)
	client := newFakeClient()
	client.byUpdateID[requestedUpdateID] = cantonclient.CantonTransaction{
		UpdateID:    mustParseUpdateID(sampleUpdateIDHex),
		EffectiveAt: time.Unix(1_700_000_001, 0).UTC(),
		Messages:    []cantonclient.CantonMessage{{Registrar: sampleRegistrar, Owner: sampleOwner, EmitterID: sampleEmitterID}},
	}

	w.handleReobservation(context.Background(), zap.NewNop(), client, &gossipv1.ObservationRequest{
		ChainId: uint32(vaa.ChainIDCanton),
		TxHash:  requestedUpdateID.TxID(),
	})
	assert.Empty(t, msgC)
}

func TestHandleReobservationWrongChainPanics(t *testing.T) {
	w := testWatcher(make(chan *common.MessagePublication, 1))
	require.Panics(t, func() {
		w.handleReobservation(context.Background(), zap.NewNop(), newFakeClient(), &gossipv1.ObservationRequest{
			ChainId: uint32(vaa.ChainIDEthereum),
			TxHash:  mustParseUpdateID(sampleUpdateIDHex).TxID(),
		})
	})
}

func TestCantonDialOptsAppendsExtraLedgerDialOpts(t *testing.T) {
	extraLedgerDialOpt := grpc.WithUserAgent("canton-watcher-test")
	completeAuth := AuthConfig{TokenURL: "https://idp.example/token", ClientID: "watcher", ClientSecret: "secret"}
	cases := []struct {
		name              string
		unsafeDevMode     bool
		auth              AuthConfig
		extraDialOpts     []grpc.DialOption
		wantDialOptsCount int
	}{
		{name: "dev mode without extras", unsafeDevMode: true, wantDialOptsCount: 0},
		{name: "dev mode with one extra", unsafeDevMode: true, extraDialOpts: []grpc.DialOption{extraLedgerDialOpt}, wantDialOptsCount: 1},
		{name: "oauth without extras", auth: completeAuth, wantDialOptsCount: 1},
		{name: "oauth with one extra", auth: completeAuth, extraDialOpts: []grpc.DialOption{extraLedgerDialOpt}, wantDialOptsCount: 2},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			w := NewWatcher("localhost:0", "", "", tc.auth, tc.unsafeDevMode, nil, nil)
			w.extraLedgerDialOpts = tc.extraDialOpts
			dialOpts := w.cantonDialOpts(context.Background())
			require.Len(t, dialOpts, tc.wantDialOptsCount)
			if len(tc.extraDialOpts) == 1 {
				assert.Same(t, extraLedgerDialOpt, dialOpts[0])
			}
			assert.Len(t, w.extraLedgerDialOpts, len(tc.extraDialOpts), "cantonDialOpts must not grow the watcher's extras")
		})
	}
}
